using UnityEngine;

/// <summary>
/// 敌人控制器 - 巡逻和碰撞检测
/// 挂载: Enemy
/// 组件: Rigidbody2D, BoxCollider2D, SpriteRenderer
/// </summary>
public class EnemyController : MonoBehaviour
{
    [Header("巡逻参数")]
    [SerializeField] private float moveSpeed = 2;
    [SerializeField] private float patrolDistance = 3;

    [Header("检测")]
    [SerializeField] private Transform wallCheck;
    [SerializeField] private Transform edgeCheck;
    [SerializeField] private LayerMask groundLayer;

    private Rigidbody2D rb;
    private SpriteRenderer spriteRenderer;
    private Vector2 startPosition;
    private int direction = 1;

    private void Awake()
    {
        rb = GetComponent<Rigidbody2D>();
        spriteRenderer = GetComponent<SpriteRenderer>();
    }

    private void Start()
    {
        startPosition = transform.position;
    }

    private void FixedUpdate()
    {
        // 巡逻移动
        rb.velocity = new Vector2(direction * moveSpeed, rb.velocity.y);

        // 翻转朝向
        if (spriteRenderer != null)
            spriteRenderer.flipX = direction < 0;

        // 墙壁检测
        bool hitWall = false;
        if (wallCheck != null)
            hitWall = Physics2D.OverlapCircle(wallCheck.position, 0.1, groundLayer);

        // 边缘检测
        bool onEdge = true;
        if (edgeCheck != null)
            onEdge = Physics2D.OverlapCircle(edgeCheck.position, 0.1, groundLayer);

        // 超出巡逻范围或碰壁或到达边缘则转向
        if (hitWall || !onEdge ||
            Mathf.Abs(transform.position.x - startPosition.x) > patrolDistance)
        {
            direction *= -1;
        }
    }

    private void OnCollisionEnter2D(Collision2D collision)
    {
        if (collision.gameObject.CompareTag("Player"))
        {
            PlayerController player = collision.gameObject.GetComponent<PlayerController>();
            if (player != null)
            {
                // 判断是否踩踏（玩家从上方落下）
                if (collision.relativeVelocity.y < -1)
                {
                    Destroy(gameObject);
                }
                else
                {
                    player.Die();
                }
            }
        }
    }
}

